package main

import (
	"fmt"
	"slices"
)

func main() {
	fmt.Println(closeStrings("", ""))
}

func closeStrings(word1 string, word2 string) bool {
	if len(word1) != len(word2) {
		return false
	}

	letters1 := make([]int, 26)
	for i := 0; i < len(word1); i++ {
		letters1[word1[i]-'a']++
	}
	letters2 := make([]int, 26)
	for i := 0; i < len(word2); i++ {
		if letters1[word2[i]-'a'] == 0 {
			return false
		}
		letters2[word2[i]-'a']++
	}

	slices.Sort(letters1)
	slices.Sort(letters2)

	return slices.Equal(letters1, letters2)
}
